import { Flow, wfa, trigger, action } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['295fbe4a37bdb6100e11a3e734924bbd'],
        name: 'test_approval_flow_sample4',
        runAs: 'user',
    },
    wfa.trigger(
        trigger.record.created,
        {
            $id: Now.ID['a15ffe4a37bdb6100e11a3e734924b3a'],
        },
        {
            table: 'incident',
            condition: '^EQ',
            run_on_extended: 'false',
            run_flow_in: 'any',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        wfa.action(
            action.core.askForApproval,
            {
                $id: Now.ID['295ffe4a37bdb6100e11a3e734924b37'],
                uuid: 'bc4210d7-d1e7-4e26-b765-4345bc0bd539',
            },
            {
                record: wfa.dataPill(_params.trigger.current, 'reference'),
                table: 'incident',
                approval_reason: 'sdsds',
                approval_field: 'approval',
                journal_field: 'approval_history',
                approval_conditions: wfa.approvalRules({
                    conditionType: 'OR',
                    ruleSets: [
                        {
                            action: 'Approves',
                            conditionType: 'AND',
                            rules: [],
                        },
                    ],
                }),
                due_date: wfa.approvalDueDate({
                    action: 'none',
                    dateType: 'actual',
                    date: '{}',
                    duration: 1,
                    durationType: 'days',
                    daysSchedule: '',
                }),
            }
        )
    }
)
